const CAMPUS_DEPARTMENT_STATS = {
  totalStudents: 180,
  averageAttendance: 37.3,
  averageCgpa: 6.51,
  totalWorkingDays: 180,
  regularEligibleCount: 12,
  condonableWarningCount: 24,
  detainedDeficitCount: 144,
  studentsWithBacklogsCount: 94,
  totalBacklogsCount: 573,
  batchYear: '2024-2025',
  scheme: 'C-24',
  collegeCode: '259',
  azureNode: 'azure.sbtet.telangana.gov.in/scet-259-c24'
};

window.CampusRoster = {
  getAll: () => CAMPUS_180_STUDENTS,
  getByPin: (pin) => CAMPUS_180_STUDENTS.find(s => s.pin.toLowerCase() === (pin || '').toLowerCase()),
  getStats: () => CAMPUS_DEPARTMENT_STATS,
  syncStudent: (pin) => {
    const s = CAMPUS_180_STUDENTS.find(item => item.pin.toLowerCase() === (pin || '').toLowerCase());
    if (s) {
      const now = new Date();
      s.lastSynced = `Just now, ${now.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}`;
    }
    return s;
  },
  massSyncFromAzure: () => {
    const now = new Date();
    const timeStr = `Just now, ${now.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}`;
    CAMPUS_180_STUDENTS.forEach(s => {
      s.lastSynced = timeStr;
    });
    return CAMPUS_DEPARTMENT_STATS;
  }
};
